class AdvancedSearch{constructor(options={}){this.SEARCH_INPUT='[data-search-input]';this.CLEAR_INPUT='[data-clear-input]';this.FILTER_TOGGLE='[data-search-filter]';this.CLEAR_ALL_FILTERS='[data-clear-all-filters]';this.CLEAR_FILTERS_GROUP='[data-clear-group-filters]';this.PAGE_NEXT='[data-page-next]';this.PAGE_PREV='[data-page-previous]';this.searchDataSelector=options.searchData??'';this.resultTemplateSelector=options.resultTemplate??'';this.filterFields=options.filterFields??null;this.activeFilters=this.filterFields??null;this.searchRanges=options.ranges??[];this.msFields=options.searchConfig?.msFields??[];this.msStoreFields=options.searchConfig?.msStoreFields??[];this.msBoostFields=options.searchConfig?.msBoostFields??null;this.searchContainerSelector=options.containers?.searchContainer??'';this.resultsContainerSelector=options.containers?.resultsContainer??'';this.paginationControlSelector=options.pagination?.paginationControls??'';this.paginationProgressSelector=options.pagination?.paginationProgressBar??'';this.resultsPerPage=options.pagination?.resultsPerPage??3;this.currentPage=1;this.pageIndexSummarySelector=options.summary?.pageIndexSummary??'';this.pageResultSummarySelector=options.summary?.pageResultSummary??'';this.noResultsSelector=options.summary?.noResultsFeedback??'';this.searchFilterMethod=options.filterLogic??this.defaultFilterLogic;this.renderTemplateMethod=options.renderLogic??null;this.initialize()}
initialize(){if(typeof MiniSearch!=='undefined'){this.miniSearch=new window.MiniSearch({fields:this.msFields,storeFields:this.msStoreFields,searchOptions:{boost:this.msBoostFields,prefix:!0,fuzzy:2}})}else{console.error("Error: MiniSearch is not loaded on this page!")}
this.setupComponent()}
setupComponent(){this.searchIndexElement=document.querySelector(this.searchDataSelector);this.setupSearchDocuments();this.resultTemplate=this.resultTemplateSelector?document.querySelector(this.resultTemplateSelector):null;this.searchContainerElement=this.searchContainerSelector?document.querySelector(this.searchContainerSelector):null;if(this.searchContainerElement){this.getSearchElements()}
this.resultsContainerElement=this.resultsContainerSelector?document.querySelector(this.resultsContainerSelector):null;this.paginationControlsElement=this.paginationControlSelector?document.querySelector(this.paginationControlSelector):null;if(this.paginationControlsElement){this.getPaginationElements()}
this.getSummaryElements();this.hasSearchInput=!!this.searchInputElement;this.hasFilters=this.searchFilterElements.length>0;this.hasRangeInputs=this.searchRanges.length>0;this.setupListeners()}
getSearchElements(){this.searchInputElement=this.searchContainerElement.querySelector(this.SEARCH_INPUT);this.clearSearchInputElement=this.searchContainerElement.querySelector(this.CLEAR_INPUT);this.searchFilterElements=Array.from(this.searchContainerElement.querySelectorAll(this.FILTER_TOGGLE));this.clearToggleGroupElements=Array.from(this.searchContainerElement.querySelectorAll(this.CLEAR_FILTERS_GROUP));this.clearToggleGroupElements.forEach(clearBtn=>{clearBtn.classList.add("hide")});this.clearAllTogglesBtnElement=this.searchContainerElement.querySelector(this.CLEAR_ALL_FILTERS);if(this.searchRanges.length>0){for(let i=0;i<this.searchRanges.length;i++){const rangeElement=this.searchRanges[i].rangeInput?this.searchContainerElement.querySelector(this.searchRanges[i].rangeInput):null;if(rangeElement){this.searchRanges[i].rangeElement=rangeElement}}}}
getPaginationElements(){this.pageNextBtn=this.paginationControlsElement.querySelector(`${this.PAGE_NEXT}`);this.pagePreviousBtn=this.paginationControlsElement.querySelector(`${this.PAGE_PREV}`);this.paginationProgressElement=this.paginationProgressSelector?document.querySelector(this.paginationProgressSelector):null}
getSummaryElements(){this.pageIndexSummaryElement=this.pageIndexSummarySelector?document.querySelector(this.pageIndexSummarySelector):null;this.pageResultSummaryElement=this.pageResultSummarySelector?document.querySelector(this.pageResultSummarySelector):null;this.noResultsElement=this.noResultsSelector?document.querySelector(this.noResultsSelector):null;this.noResultsElement.style.display="none"}
setupListeners(){this.searchContainerElement.querySelector('form')?.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault()}});if(this.hasSearchInput){let timer;this.searchInputElement.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{this.executeSearch()},this.debounceTime)});if(this.clearSearchInputElement){this.clearSearchInputElement.addEventListener('click',()=>{this.clearSearchInput()})}}
if(this.hasRangeInputs){this.searchRanges.forEach(range=>{if(range.rangeElement){if(typeof range.rangeInitiateMethod==='function'){range.rangeInitiateMethod(range.rangeElement,range.rangeFields)}
range.rangeElement.addEventListener(range.rangeEvent,(e)=>{if(typeof range.rangeEventMethod==='function'){range.rangeEventMethod(e,range.rangeFields)}
this.executeSearch()})}})}
if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.updateActiveFilters(e);this.executeSearch()})});this.clearToggleGroupElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.clearFilterCategory(e)})});if(this.clearAllTogglesBtnElement){this.clearAllTogglesBtnElement.addEventListener('click',()=>{this.clearAllFilters()})}}
if(this.resetSearchBtnElement){this.resetSearchBtnElement.addEventListener('click',()=>{this.resetSearch()})}
if(this.pageNextBtn){this.pageNextBtn.addEventListener('click',()=>{this.goToNextPage()})}
if(this.pagePreviousBtn){this.pagePreviousBtn.addEventListener('click',()=>{this.goToPreviousPage()})}
if(window.location.search){this.setDefaultSearchFromURL()}
this.executeSearch()}
setupSearchDocuments(){if(!this.searchIndexElement){console.warn(`Faceted Search: Could not find script element with ID "${this.searchDataSelector}".`);return}else{try{const parsedJSON=JSON.parse(this.searchIndexElement.textContent);this.searchDocs=parsedJSON.map((item,index)=>({...item,id:index}));this.initializeMiniSearch(this.searchDocs)}catch(error){console.error('Faceted Search: Failed to parse JSON data.',error)}}}
initializeMiniSearch(searchDocuments){if(Array.isArray(searchDocuments)){this.miniSearch.addAll(searchDocuments)}}
executeSearch(){const query=this.searchInputElement.value.toLowerCase().trim();if(query===""){this.results=this.searchDocs.filter(item=>{return this.filterSearchResult(item)})}else{this.results=this.miniSearch.search(query,{filter:(result)=>{return this.filterSearchResult(result)}})}
this.buildURLEndpoint();this.toggleNoResults();this.updatePaginationResults(this.results)}
filterSearchResult(result){const hasTagMatch=this.searchFilterMethod(result,this.activeFilters);const isRangeMatch=()=>{return this.searchRanges.every(range=>{if(range.rangeElement&&typeof range.rangeFilterLogic==='function'){return range.rangeFilterLogic(result,range.rangeFields)}
return!0})};const hasRangeMatch=this.hasRangeInputs?isRangeMatch():!0;if(hasTagMatch&&hasRangeMatch){return!0}
return!1}
setDefaultSearchFromURL(){const searchQueryString=decodeURIComponent(window.location.search);const searchParameters=new URLSearchParams(searchQueryString);this.searchInputElement.value=searchParameters.get("query")||"";Object.keys(this.activeFilters).forEach(category=>{if(searchParameters.has(category)){const value=searchParameters.get(category);this.activeFilters[category]=value?value.split(","):[]}});this.setFilterToggles()}
clearSearchInput(){this.searchInputElement.value="";this.executeSearch()}
defaultFilterLogic(result,activeFilters){return Object.entries(activeFilters).every(([category,activeTags])=>{if(activeTags.length===0)
return!0;const resultCategoryTags=result[category];if(Array.isArray(resultCategoryTags)){return resultCategoryTags.some(tag=>activeTags.includes(tag))}
return activeTags.includes(resultCategoryTags)})}
updateActiveFilters(e){const{name,value}=e.currentTarget;const currentCategory=this.activeFilters[name];const tagIndex=currentCategory.indexOf(value);if(tagIndex>-1){currentCategory.splice(tagIndex,1)}else{currentCategory.push(value)}
this.toggleClearGroupButton(currentCategory.length,name)}
setFilterToggles(){Object.entries(this.activeFilters).forEach(([category,tags])=>{const categoryBtns=this.searchFilterElements.filter(toggle=>{return toggle.name===category});tags.forEach(tag=>{categoryBtns.forEach((toggle)=>{if(toggle.value===tag)
toggle.checked=!0})});this.toggleClearGroupButton(tags.length,category)})}
clearFilterCategory(e){const{name}=e.currentTarget;const currentCategory=this.activeFilters[name];const categoryBtns=this.searchFilterElements.filter(toggle=>{return toggle.name===name});categoryBtns.forEach(toggle=>{toggle.checked=!1});currentCategory.length=0;this.toggleClearGroupButton(currentCategory.length,name);this.executeSearch()}
clearAllFilters(){this.searchFilterElements.forEach(toggle=>{toggle.checked=!1});Object.keys(this.activeFilters).forEach(category=>{this.activeFilters[category].length=0;this.toggleClearGroupButton(0,category)});this.executeSearch()}
defaultRangeLogic(result,activeRanges){}
updatePaginationResults(results){if(!Array.isArray(results))
return;this.totalPages=Math.ceil(results.length/this.resultsPerPage);this.currentPage=1;this.displayPage(this.currentPage)}
displayPage(page){const startIndex=(page-1)*this.resultsPerPage;const endIndex=Math.min(startIndex+this.resultsPerPage,this.results.length);const pageItems=this.results.slice(startIndex,endIndex);this.renderPageResults(pageItems,startIndex,endIndex)}
renderPageResults(results,startIndex,endIndex){this.resultsContainerElement.innerHTML='';const pageFragment=new DocumentFragment();results.forEach(result=>{this.renderTemplateMethod(result,pageFragment,this.resultTemplate)});this.resultsContainerElement.appendChild(pageFragment);this.updatePaginationControls();this.updatePaginationSummary(startIndex,endIndex)}
goToNextPage(){if(this.currentPage<this.totalPages){this.currentPage++;this.displayPage(this.currentPage)}}
goToPreviousPage(){if(this.currentPage>1){this.currentPage--;this.displayPage(this.currentPage)}}
toggleClearGroupButton(count,name){const clearGroupBtn=this.getClearToggleGroupBtn(name);if(count>0){if(clearGroupBtn.classList.contains("hide")){clearGroupBtn.classList.remove("hide");clearGroupBtn.removeAttribute("disabled")}}else{clearGroupBtn.classList.add("hide");clearGroupBtn.setAttribute("disabled","")}}
toggleNoResults(){if(this.results.length===0){this.noResultsElement.style.display=""}else{this.noResultsElement.style.display="none"}}
updatePaginationSummary(startIndex,endIndex){const resultsLength=this.results.length;if(this.pageResultSummaryElement)
this.pageResultSummaryElement.textContent=(resultsLength>=1)?`Showing (${startIndex + 1} - ${endIndex}) of (${resultsLength}) results`:"No Results";if(this.pageIndexSummaryElement)
this.pageIndexSummaryElement.textContent=(resultsLength>=1)?`Page ${this.currentPage} of ${this.totalPages}`:"";if(this.paginationProgressElement){const progressFill=this.paginationProgressElement.querySelector(".progress-bar");const progress=Math.floor((resultsLength>=1)?(this.currentPage/this.totalPages)*100:0);this.paginationProgressElement.setAttribute("aria-valuenow",progress);progressFill.style.width=`${progress}%`}}
updatePaginationControls(){this.pagePreviousBtn.disabled=this.currentPage===1;this.pageNextBtn.disabled=this.currentPage===this.totalPages}
resetSearch(){this.searchInputElement.value="";this.clearAllFilters()}
getClearToggleGroupBtn(groupName){return this.clearToggleGroupElements.find(clearBtn=>clearBtn.name===groupName)??null}
buildURLQuery(data){let searchParameters=new URLSearchParams(data);let emptyNullKeys=[];searchParameters.forEach((value,key)=>{if(value===''){emptyNullKeys.push(key)}});emptyNullKeys.forEach(key=>{searchParameters.delete(key)});return searchParameters.toString()}
buildURLEndpoint(){const basePath=window.location.pathname;const query=this.searchInputElement.value.toLowerCase().trim();const finalParameterObject={query,...this.activeFilters};const newQueries=`${this.buildURLQuery(finalParameterObject)}`;const endpoint=`${basePath}?${newQueries}`;window.history.replaceState(null,'',endpoint)}}